#!/usr/bin/env python3
"""Build a static reading site from the single book manifest and Markdown sources."""
from pathlib import Path
import argparse,html,json,re,shutil,struct,zipfile
from urllib.parse import quote
import markdown
from markdown.extensions.toc import slugify_unicode

ROOT=Path(__file__).resolve().parents[1]
REPO='https://github.com/YZYExp/Learn-Colorful'
DESCRIPTIONS=['从光、物体与眼睛开始，建立描述颜色的语言。','理解明暗、彩度、面积与冷暖，安排画面的主次。','把情绪、文化、材料和风格放回具体语境。','从取色到应用，动手诊断并修正一套配色。','走进品牌、界面、服饰、产品与空间。','把颜色整理成角色、主题与可交付的规则。']
PART_COLORS=['#24544B','#C86345','#244799','#AA8431','#6A345A','#465E70']

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--base-path',default='/Learn-Colorful/');parser.add_argument('--output',default='build/site');parser.add_argument('--epub',type=Path);args=parser.parse_args()
    if not args.base_path.startswith('/') or '..' in args.base_path or '?' in args.base_path or '#' in args.base_path:raise SystemExit('base-path must be an absolute URL path')
    base=args.base_path.rstrip('/')+'/' if args.base_path!='/' else '/'
    out=(ROOT/args.output).resolve()
    if not out.is_relative_to(ROOT/'build'):raise SystemExit('Output must stay beneath build/')
    out.mkdir(parents=True,exist_ok=True)
    # Only remove files previously generated by this builder, never source material.
    old=out/'generated-files.json'
    if old.exists():
        for name in json.loads(old.read_text()):
            f=(out/name).resolve()
            if f.is_relative_to(out) and f.is_file():f.unlink()
    b=json.loads((ROOT/'book.json').read_text());docs=b['frontmatter']+b['chapters']+b['backmatter'];routes={}
    for c in docs:
        c['route']='read/'+c['slug']+'/';routes[(ROOT/c['source']).resolve()]=c['route']
    generated=[]
    def write(path,text):
        file=out/path;file.parent.mkdir(parents=True,exist_ok=True);file.write_text(text);generated.append(path)
    def copy(source,dest):
        target=out/dest;target.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(source,target);generated.append(dest)
    def url(path=''):return base+path
    def link(c):return url(c['route'])
    def esc(text):return html.escape(str(text),quote=True)
    def nav(current):
        groups=[]
        def entry(c):return f'<li><a href="{link(c)}"'+(' aria-current="page"' if c['source']==current else '')+f'>{esc((str(c["order"]).zfill(2)+" · ") if "order" in c else "")}{esc(c["title"])}</a></li>'
        groups.append('<ul>'+''.join(entry(c) for c in b['frontmatter'])+'</ul>')
        for part,title in enumerate(b['parts'],1):groups.append(f'<h3>{part:02} / {esc(title)}</h3><ul>'+''.join(entry(c) for c in b['chapters'] if c['part']==part)+'</ul>')
        groups.append('<h3>附录与练习</h3><ul>'+''.join(entry(c) for c in b['backmatter'])+'</ul>')
        return '<details class="book-nav" open><summary>全书目录 · 展开 / 收起</summary>'+''.join(groups)+'</details>'
    def page(title,body,reader=False,description=None):
        description=description or '图解色彩知识读本：从看懂颜色到建立配色系统，六篇二十四章，配合观察实验与实际应用。'
        full_title=title+' · '+b['subtitle'] if title==b['title'] else title+' · '+b['title']
        return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{esc(description)}"><meta name="theme-color" content="#F8F5EE"><title>{esc(full_title)}</title><link rel="icon" href="{url('favicon.svg')}" type="image/svg+xml"><link rel="stylesheet" href="{url('style.css')}"><script src="{url('app.js')}" defer></script></head><body data-base="{base}"><a class="skip" href="#main">跳到正文</a><div class="progress" aria-hidden="true"></div><header class="site-header"><a class="brand" href="{base}"><span class="brand-mark" aria-hidden="true"><i></i><i></i><i></i></span>色彩的语言</a><nav class="top-nav" aria-label="主导航"><a href="{base}#contents">目录</a><a href="{base}#search">搜索</a><a class="repo-link" href="{REPO}">GitHub ↗</a><button class="icon-button" type="button" data-theme-toggle aria-label="切换深色模式">◐</button></nav></header>{body}<footer class="site-footer"><span>色彩的语言 · 从看懂颜色到建立配色系统</span><span><a href="{link(b['frontmatter'][0])}">阅读说明</a> · <a href="{REPO}">书稿与来源 ↗</a></span></footer></body></html>'''
    # PNG dimensions come from the header; no font or image-processing dependency.
    asset_names=set()
    def image_tag(source,alt,eager=False):
        if not source.is_file() or not source.resolve().is_relative_to(ROOT):raise SystemExit('Invalid image '+str(source))
        dest='assets/images/'+source.name
        if dest not in asset_names:copy(source,dest);asset_names.add(dest)
        data=source.read_bytes()[:24]
        if data[:8]!=b'\x89PNG\r\n\x1a\n':raise SystemExit('Expected PNG '+str(source))
        width,height=struct.unpack('>II',data[16:24])
        return f'<img src="{url(dest)}" alt="{esc(alt)}" width="{width}" height="{height}" loading="{"eager" if eager else "lazy"}" decoding="async">'
    index=[]
    for i,c in enumerate(docs):
        src=ROOT/c['source'];raw=src.read_text()
        md=markdown.Markdown(extensions=['markdown.extensions.tables','markdown.extensions.fenced_code','markdown.extensions.toc'],extension_configs={'markdown.extensions.toc':{'slugify':slugify_unicode,'toc_depth':'2-3'}})
        body=md.convert(raw)
        def replace_image(m):
            attrs=m.group(0);sm=re.search(r'src="([^"]+)"',attrs);am=re.search(r'alt="([^"]*)"',attrs)
            if not sm:raise SystemExit('Image missing src')
            target=(src.parent/html.unescape(sm.group(1))).resolve();tag=image_tag(target,html.unescape(am.group(1)) if am else '')
            return f'<a class="image-link" href="{url("assets/images/"+target.name)}" target="_blank" rel="noopener" aria-label="在新标签页查看大图">{tag}</a>'
        body=re.sub(r'<img\b[^>]*>',replace_image,body)
        def replace_href(m):
            target=html.unescape(m.group(1))
            if target.startswith(('http:','https:','mailto:','#')):return m.group(0)
            path,sep,anchor=target.partition('#');dest=routes.get((src.parent/path).resolve())
            if dest:return 'href="'+url(dest)+(('#'+quote(anchor)) if sep else '')+'"'
            raise SystemExit(f'Unresolved chapter link: {src.name}: {target}')
        body=re.sub(r'href="([^"]+)"',lambda m:m.group(0) if m.group(1).startswith(base+'assets/') else replace_href(m),body)
        body=re.sub(r'(<table>.*?</table>)',r'<div class="table-scroll">\1</div>',body,flags=re.S)
        toc='<details class="chapter-toc"><summary>本章要点</summary>'+md.toc+'</details>' if md.toc_tokens else ''
        prev=docs[i-1] if i else None;nextdoc=docs[i+1] if i+1<len(docs) else None
        pager='<nav class="chapter-pager" aria-label="前后篇导航">'+(f'<a href="{link(prev)}"><small>← 上一篇</small>{esc(prev["title"])}</a>' if prev else '<a href="'+base+'"><small>← 返回</small>阅读主页</a>')+(f'<a href="{link(nextdoc)}"><small>下一篇 →</small>{esc(nextdoc["title"])}</a>' if nextdoc else '<a href="'+base+'#contents"><small>阅读完成</small>回到全书目录 →</a>')+'</nav>'
        category=f'第{c["part"]}篇 · '+b['parts'][c['part']-1] if 'part' in c else '导读与附录'
        article=f'<div class="reader-layout">{nav(c["source"])}<main class="reader-main" id="main"><p class="breadcrumb"><a href="{base}">首页</a> / {esc(category)}</p><div class="reading-tools"><span>字号</span><button type="button" data-font="-1" aria-label="缩小字号">A−</button><button type="button" data-font="1" aria-label="放大字号">A＋</button></div>{toc}<article class="prose">{body}</article>{pager}<a class="back-to-top" href="#main">回到本章开头 ↑</a></main></div>'
        write(c['route']+'index.html',page(c['title'],article,True))
        text=html.unescape(re.sub('<[^>]+>',' ',body));text=re.sub(r'\s+',' ',text).strip()
        index.append({'title':c['title'],'url':link(c),'text':text})
    parts=[]
    for num,title in enumerate(b['parts'],1):
        entries=''.join(f'<li><a href="{link(c)}"><span>{c["order"]:02}</span>{esc(c["title"])}<em aria-hidden="true">↗</em></a></li>' for c in b['chapters'] if c['part']==num)
        parts.append(f'<section class="part" style="--part-color:{PART_COLORS[num-1]}"><div class="part-band"></div><div class="part-inner"><div class="part-head"><span class="part-num">{num:02}</span><h3>{esc(title)}</h3></div><p>{DESCRIPTIONS[num-1]}</p><ol class="chapter-list">{entries}</ol></div></section>')
    palettes=[]
    for study in json.loads((ROOT/'references/palette-studies.json').read_text()):
        n=study['id'];image=image_tag(ROOT/f'assets/images/palette-{n:02}.png',study['title']+'在同一海报中的应用')
        palettes.append(f'<div class="palette-card"><a href="{link(b["backmatter"][-1])}#'+str(n)+'-'+quote(study['title'])+f'">{image}</a><div class="palette-caption"><strong>{n:02} / {esc(study["title"])}</strong><span>同版式 · 不同关系</span></div></div>')
    download=f'<a href="{REPO}/actions/workflows/ebook.yml">EPUB 下载入口 ↗</a><p>在最近一次成功运行的 Artifacts 中下载，需登录 GitHub。</p>'
    if args.epub:
        if not args.epub.is_file() or not zipfile.is_zipfile(args.epub):raise SystemExit('Explicit EPUB path is invalid')
        copy(args.epub,'downloads/color-language.epub');download=f'<a class="button" href="{url("downloads/color-language.epub")}">下载 EPUB</a>'
    cover=image_tag(ROOT/b['cover'],'《色彩的语言》封面',True)
    ribbon=''.join(f'<i style="background:{c}"></i>' for c in ['#24544B','#B9D9CE','#C86345','#E2BC39','#244799','#6A345A','#465E70','#202824'])
    extra=''.join(f'<li><a href="{link(c)}">{esc(c["title"])}</a></li>' for c in b['backmatter'])
    home=f'''<main id="main" class="shell"><section class="hero"><div><div class="eyebrow">COLOR · PERCEPTION · DESIGN</div><h1>看懂颜色，<br>才会<span>用颜色。</span></h1><p class="hero-copy">一张色卡只是起点。从光与视觉，到海报、界面和空间，一起理解颜色为什么这样搭，又该怎样改。</p><div class="hero-actions"><a class="button primary" href="{link(b['frontmatter'][0])}">开始阅读 →</a><a class="button" href="#contents">浏览全书目录</a><a class="button" data-resume hidden href="{link(b['frontmatter'][0])}">继续阅读 →</a></div><div class="facts"><span><b>06</b>篇</span><span><b>24</b>章</span><span><b>37</b>幅配图</span></div></div><div class="book-stage">{cover}</div></section><div class="color-ribbon" aria-hidden="true">{ribbon}</div><section id="search" class="search-section"><label class="search-field" for="chapter-search"><span aria-hidden="true">⌕</span><input id="chapter-search" type="search" placeholder="寻找一个问题：明度、材料、深色主题……" autocomplete="off"><kbd>/</kbd></label><p id="search-status" class="status" role="status" aria-live="polite"></p><ul id="search-results" class="search-results"></ul></section><section id="contents"><div class="section-heading"><div><div class="eyebrow">THE READING PATH</div><h2>从看见，到建立系统</h2><p>六条相连的学习路径，也可以从你关心的问题开始。</p></div><a href="{link(b['frontmatter'][0])}">怎样读这本书 ↗</a></div><div class="parts-grid">{''.join(parts)}</div></section><section class="atlas-section" id="palettes"><div class="section-heading"><div><div class="eyebrow">SAME LAYOUT, DIFFERENT COLORS</div><h2>让配色进入画面</h2><p>八组原创配色，用同一张海报比较颜色的分工与关系。</p></div><a href="{link(b['backmatter'][-1])}">阅读分析 ↗</a></div><div class="atlas-grid">{''.join(palettes)}</div></section><section class="resources"><div><h3>边看，边试，边调整</h3><p>用观察练习、术语和对照案例，把“觉得好看”变成说得清的判断。</p><ul>{extra}</ul></div><div id="downloads"><h3>离线阅读与书稿</h3><p>网页与电子书使用同一份分章正文，参考资料就在对应章节中。</p>{download}<a href="{REPO}">查看书稿、图片与来源 ↗</a></div></section></main>'''
    write('index.html',page(b['title'],home))
    write('404.html',page('页面未找到',f'<main id="main" class="shell"><section class="hero"><div><div class="eyebrow">404</div><h1>换一条路径，<br>继续阅读。</h1><p>这个地址没有对应的章节。</p><a class="button primary" href="{base}">回到全书目录 →</a></div></section></main>'))
    write('search-index.json',json.dumps(index,ensure_ascii=False));write('.nojekyll','')
    write('favicon.svg','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48"><rect width="48" height="48" rx="10" fill="#F6F1E7"/><path fill="#24544B" d="M8 10h9v28H8z"/><path fill="#C86345" d="M20 10h9v28h-9z"/><path fill="#244799" d="M32 10h9v28h-9z"/></svg>')
    copy(ROOT/'site/style.css','style.css');copy(ROOT/'site/app.js','app.js')
    write('generated-files.json',json.dumps(generated,ensure_ascii=False,indent=2))
    print(json.dumps({'pages':len(docs)+2,'images':len(asset_names),'base_path':base,'output':str(out)},ensure_ascii=False))

if __name__=='__main__':main()
